INSERT IGNORE INTO notices (id, college_id, title, content, target_audience, priority, publish_date, expiry_date, created_by, status) VALUES
('notice-001','col-001','Mid-Semester Examination Schedule Released','Dear Students and Parents, the Mid-Semester Examination schedule for October 2026 has been officially released. Exams will commence from 28th October 2026. Students are advised to check their individual timetables and prepare accordingly. Hall tickets will be distributed by class teachers on 25th October 2026. No student will be allowed to appear without a valid hall ticket.','ALL','URGENT','2026-10-20','2026-11-05','user-admin','PUBLISHED'),
('notice-002','col-001','Annual Cultural Fest - MIT Utsav 2026','We are delighted to announce MIT Utsav 2026, our annual cultural extravaganza! The event is scheduled for 15th November 2026 at the college auditorium. Students can register for dance, music, drama, art, and literary events. Registration forms are available at the Student Affairs office. Last date to register: 5th November 2026.','ALL','HIGH','2026-10-19','2026-11-15','user-admin','PUBLISHED'),
('notice-003','col-001','Fee Payment Reminder - October 2026','This is a reminder to all students and parents regarding the pending semester fee payment. The last date for fee payment without a late fine is 31st October 2026. Students who fail to pay fees by the due date will be charged a late fine of Rs. 500 per week. Parents are requested to ensure timely payment to avoid any inconvenience.','PARENTS','HIGH','2026-10-18','2026-10-31','user-admin','PUBLISHED'),
('notice-004','col-001','Library Extended Hours During Exam Period','Please note that the library will remain open from 7:00 AM to 10:00 PM during the examination period from 28th October to 15th November 2026. Students are encouraged to utilize the extended library hours for exam preparation. Silence must be maintained. Reference books for all subjects are available at the library helpdesk.','ALL','NORMAL','2026-10-17','2026-11-15','user-admin','PUBLISHED'),
('notice-005','col-001','Parent-Teacher Meeting - 8th November 2026','A Parent-Teacher Meeting is scheduled for 8th November 2026 (Saturday) from 10:00 AM to 1:00 PM. Parents are requested to meet their ward class teacher to discuss academic progress, attendance, and behavior. Your presence is mandatory. Kindly bring your ward along. The meeting will be held in the respective classrooms.','PARENTS','URGENT','2026-10-16','2026-11-08','user-admin','PUBLISHED'),
('notice-006','col-001','MIT Sports Week 2026 Registrations Open','MIT Sports Week 2026 will be held from 10th to 14th November 2026. Events include cricket, football, basketball, volleyball, badminton, and athletics. Students must register with their department sports coordinator by 1st November 2026. Certificates and trophies will be awarded to all winners.','STUDENTS','NORMAL','2026-10-15','2026-11-14','user-admin','PUBLISHED');
